pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let post_res = post_residual as f64;

    // Base heuristic: prioritize tightest fit (Best Fit).
    // Use a power law to disproportionately penalize mid-sized residuals that are 
    // too large to be useful but too small to fit the next item efficiently.
    let mut score = post_res.powf(1.2);

    if is_new_bin {
        // Dynamic barrier: opening a new bin is penalized based on total stream progress.
        // We start with a baseline cost and increase it as the stream nears completion
        // to force consolidation into existing bins.
        score = 32.0 + (progress * 55.0);
    } else {
        // Reward existing bins that keep the mean residual stable, reducing fragmentation.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.4;

        // Lookahead: If the post_residual is smaller than the next item, we create 'dead space'.
        // Penalize this 'dead space' more heavily early in the stream.
        if next_item_size > 0 && post_res < next_item_size as f64 {
            score += 45.0 * (1.0 - progress);
        }

        // Penalty for "sliver" gaps (residual 1-12) which are statistically hard to fill.
        if post_residual > 0 && post_residual <= 12 {
            score += 18.0 * (1.0 - progress * 0.5);
        }
    }

    // If this is the only bin that fits, strongly incentivize using it to prevent 
    // unnecessary new bin allocation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 22.0;
    }

    // Secondary load balancing: favor bins that are already partially filled.
    // This encourages filling existing bins towards capacity rather than starting new ones.
    let current_load_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= current_load_ratio * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins tight.
    // However, if fitting_bins_count is 1, we are forced to accept this bin if we don't open a new one.
    // We dampen the penalty when we have few choices.
    score += post_residual as f64 * (1.0 / (fitting_bins_count as f64 + 0.1));

    // 2. Lookahead Matching (The "Aggressive" Component):
    // If we have a next item, we want to minimize the gap between the post_residual and the next item size.
    // If post_residual is slightly larger than next_item_size, it's a perfect match.
    // If post_residual is smaller than next_item_size, we penalize heavily (fragmentation).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (bin_capacity - post_residual) as f64 * 0.5;
            score += (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += (next_item_size - post_residual) as f64 * 5.0;
        }
    }

    // 3. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current mean state of the system.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // 4. New Bin Logic:
    // If bin_residual == bin_capacity, this is a request to open a new bin.
    // We only open a new bin if the current "best" fit is truly terrible (high post_residual).
    if bin_residual == bin_capacity {
        // High threshold: only open a new bin if the average residual is already quite low
        // or if we are nearing the end of the stream and need to clear space.
        score = 45.0 + (mean_residual * 0.5) - (step_index as f64 / total_items as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual (Minimize score)
    // 2. Penalty for creating "dead space": if post_residual is in the "unusable" range (1-9), penalize heavily
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead logic: if next_item_size is known, favor bins that can accommodate it later
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that are perfectly sized for the next item (harmonic affinity)
            score -= (bin_capacity as f64 - (post_residual as f64 - next_item_size as f64)) / 2.0;
        } else {
            // Penalize bins that will be too small for the next item if they are currently "tight"
            score += 15.0;
        }
    }

    // 4. Global state awareness: discourage opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only consider new bin if it's the only option or if current open bins are high-fragmentation
        if fitting_bins_count > 0 {
            score += 60.0 + (mean_residual * 0.5);
        } else {
            score -= 20.0;
        }
    }

    // 5. Harmonic refinement: Use modulo to find "clean" fits (multiples of 20 or 25 are often optimal)
    let remainder = post_residual % 20;
    if remainder == 0 {
        score -= 10.0;
    } else if remainder > 15 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prioritize smaller post_residuals (Best Fit)
    // but penalize them quadratically to avoid leaving tiny, unusable gaps.
    let mut score = (post_residual as f64).powf(1.8);

    // If this is a new bin, apply a dynamic cost.
    // As the stream progresses, opening new bins becomes increasingly expensive
    // relative to the "waste" created by fitting into an existing tight spot.
    if is_new_bin {
        score = 45.0 + (progress * 80.0);
    } else {
        // Reward bins that bring the residual closer to the mean of existing bins
        // to encourage uniform fill distribution across open bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // Lookahead heuristic: If the next item fits into the current post_residual,
        // provide a significant bonus to keep the bin open.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64) * 1.5;
        }

        // Penalty for leaving a bin in a "near-empty" state (e.g., 1-15 space left)
        // which is statistically unlikely to be filled by future items.
        if post_residual > 0 && post_residual < 15 {
            score += 20.0 * (1.0 - progress);
        }
    }

    // If this is the last fitting bin, slightly decrease the penalty 
    // to prevent unnecessary bin creation unless the fit is truly atrocious.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let load_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Core: Use a tighter exponential penalty for the residual to prioritize exact fits.
    let mut score = post_res.powf(1.35);

    if is_new_bin {
        // Dynamic barrier: escalate cost to open new bins based on progress and current open count.
        // Penalty is increased to force usage of existing bins when possible.
        let base_new_penalty = 48.0 + (55.0 * progress.powf(0.85));
        let open_bin_penalty = (open_bins_count as f64 * 0.35).min(50.0);
        score = base_new_penalty + open_bin_penalty;
    } else {
        // Deviation from mean residual to reduce local fragmentation.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 1.1;

        // Lookahead: If the current placement leaves a gap smaller than the next item, 
        // it effectively "strands" that capacity. Heavily penalize this.
        if next_item_size > 0 {
            if post_res < next_item_size as f64 {
                score += (next_item_size as f64 - post_res) * 12.0;
            } else {
                // Reward bins that have a "near-fit" (within 10% of capacity) for the next item.
                score -= (post_res - next_item_size as f64).min(10.0) * 0.5;
            }
        }

        // Consolidation: Favor bins that are already well-filled to minimize the count of active bins.
        score -= load_ratio * 55.0;

        // Adaptive packing: if item is large, aggressively prioritize bins with high current load.
        if item_size > 50 {
            score -= load_ratio * 30.0;
        }

        // Criticality: If very few bins work, force usage to prevent unnecessary new bin allocation.
        if fitting_bins_count <= 2 {
            score -= 145.0 * (1.0 - (fitting_bins_count as f64 * 0.1));
        }
    }

    // Entropy dampener: discourage "micro-gaps" which are often dead space.
    // Modulate penalty to be harsher when the bin is already significantly loaded.
    if post_res > 0.0 && post_res < 15.0 {
        score += 40.0 * (1.0 - (load_ratio * 0.5));
    }

    // Trend alignment: reward bins that keep the residual below the global mean.
    if post_res < mean_residual {
        score -= 12.0 * (1.0 - progress);
    }

    // Global pressure: If we have too many open bins, penalize new bin creation and poor fits.
    if open_bins_count > (total_items / 100).max(12) {
        score += post_res * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
