        score = 42.0 + (65.0 * progress.powf(0.6)) + (open_bins_count as f64 * 0.15);
    } else {
        // 1. Lookahead: Stronger penalty for stranding the next item in a small gap.
        if next_item_size > 0 {
            if post_res < next_item_size as f64 {
                score += (next_item_size as f64 - post_res) * 8.5;
            } else {
                // Reward bins that have a "near-fit" for the next item.
                score -= (post_res - next_item_size as f64) * 0.8;
            }
        }

        // 2. Fitting pressure: If we have very few options, we MUST prioritize 
        // the available bin to avoid unnecessary new bin creation.
        if fitting_bins_count <= 2 {
            score -= 120.0 * (1.0 - (fitting_bins_count as f64 * 0.2));
        }

        // 3. Mean Residual Balancing:
        // Penalize deviations from the mean to promote uniform bin usage.
        score += (post_res - mean_residual).abs() * 1.5;

        // 4. Entropy Control:
        // Discourage "micro-gaps" that are too small to be useful for future large items.
        if post_res > 0.0 && post_res < 12.0 {
            score += 25.0;
        }

        // 5. Load Weighting:
        // Favor bins that are already well-filled to minimize the count of active bins.
        let usage = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= usage * 40.0;
    }

    // Global constraint: If we have too many open bins, penalize any bin that leaves a large gap.
    if open_bins_count > (total_items / 100).max(15) {
        score += post_res * 1.2;
    }

    score
}
